import{_ as d,C as s,o as e,c as r,a2 as l,b as E,w as a,a as i,E as o,a3 as C}from"./chunks/framework.BBdhqAg0.js";const g="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"기안 양식 안내 (18종 전용 서식)","description":"","frontmatter":{},"headers":[],"relativePath":"approval/forms.md","filePath":"approval/forms.md","lastUpdated":1793109310000}'),A={name:"approval/forms.md"};function B(x,t,y,h,f,c){const n=s("Mermaid");return e(),r("div",null,[t[1]||(t[1]=l('<h1 id="기안-양식-안내-18종-전용-서식" tabindex="-1">기안 양식 안내 (18종 전용 서식) <a class="header-anchor" href="#기안-양식-안내-18종-전용-서식" aria-label="Permalink to &quot;기안 양식 안내 (18종 전용 서식)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+g+'" alt="기안 양식 선택 및 작성 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/forms.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>IBS 전자결재 시스템</strong>은 단순 텍스트 입력을 넘어, 사내 업무 도메인(인사, 회계, 법무, 부동산 개발 사업 등)에 최적화된 <strong>18종 전용 서식</strong>과 유연한 <strong>동적 맞춤형 폼</strong>을 제공합니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[전자결재 시스템] → [문서 기안 및 작성] → [기안 양식 안내 (18종)]**을 선택하여 접속합니다.</li></ul><h2 id="_1-18종-전용-서식-카테고리-구조" tabindex="-1">1. 18종 전용 서식 카테고리 구조 <a class="header-anchor" href="#_1-18종-전용-서식-카테고리-구조" aria-label="Permalink to &quot;1. 18종 전용 서식 카테고리 구조&quot;">​</a></h2>',5)),(e(),E(C,null,{default:a(()=>[o(n,{id:"mermaid-23",class:"mermaid",graph:"mindmap%0A%20%20root((18%EC%A2%85%20%EC%A0%84%EC%9A%A9%20%EC%84%9C%EC%8B%9D))%0A%20%20%20%201.%20%EC%9D%BC%EB%B0%98%2F%EA%B3%B5%ED%86%B5%0A%20%20%20%20%20%20%EC%9D%BC%EB%B0%98%20%EC%97%85%EB%AC%B4%20%ED%92%88%EC%9D%98%EC%84%9C%0A%20%20%20%20%20%20%EA%B3%B5%EB%AC%B8%20%EB%B0%9C%EC%8B%A0%20%ED%92%88%EC%9D%98%EC%84%9C%0A%20%20%20%20%20%20%EC%88%98%EC%8B%A0%20%EA%B3%B5%EB%AC%B8%20%EC%A0%91%EC%88%98%EB%B3%B4%EA%B3%A0%20%EB%B0%8F%20%EB%8C%80%EC%9D%91%20%ED%92%88%EC%9D%98%EC%84%9C%0A%20%20%20%202.%20%EC%9D%B8%EC%82%AC%2F%EA%B7%BC%ED%83%9C%0A%20%20%20%20%20%20%ED%9C%B4%EA%B0%80%2F%EC%97%B0%EC%B0%A8%20%EC%8B%A0%EC%B2%AD%EC%84%9C%0A%20%20%20%20%20%20%EC%B6%9C%EC%9E%A5%20%EC%8B%A0%EC%B2%AD%EC%84%9C%0A%20%20%20%20%20%20%EC%97%B0%EC%9E%A5%2F%ED%9C%B4%EC%9D%BC%EA%B7%BC%EB%AC%B4%20%EC%8B%A0%EC%B2%AD%EC%84%9C%0A%20%20%20%20%20%20%EC%9D%B8%EC%82%AC%20%EB%B0%9C%EB%A0%B9%20%ED%92%88%EC%9D%98%EC%84%9C%0A%20%20%20%20%20%20%EC%9D%B8%EC%82%AC%20%EA%B4%80%EB%A0%A8%20%EC%8B%A0%EC%B2%AD%EC%84%9C%0A%20%20%20%203.%20%ED%9A%8C%EA%B3%84%2F%EC%9E%90%EA%B8%88%0A%20%20%20%20%20%20%EA%B5%AC%EB%A7%A4%20%ED%92%88%EC%9D%98%EC%84%9C%0A%20%20%20%20%20%20%EC%A7%80%EC%B6%9C%20%EA%B2%B0%EC%9D%98%EC%84%9C%0A%20%20%20%20%20%20%EA%B2%BD%EB%B9%84%20%EC%A0%95%EC%82%B0%EC%84%9C%0A%20%20%20%20%20%20%EC%84%A0%EA%B8%89%EA%B8%88%2F%EA%B0%80%EC%A7%80%EA%B8%89%EA%B8%88%20%EC%8B%A0%EC%B2%AD%EC%84%9C%0A%20%20%20%204.%20%EA%B3%84%EC%95%BD%2F%EB%B2%95%EB%AC%B4%0A%20%20%20%20%20%20%EA%B3%84%EC%95%BD%20%EC%B2%B4%EA%B2%B0%20%ED%92%88%EC%9D%98%EC%84%9C%0A%20%20%20%20%20%20%EA%B3%84%EC%95%BD%20%EB%B3%80%EA%B2%BD%2F%ED%95%B4%EC%A7%80%20%ED%92%88%EC%9D%98%EC%84%9C%0A%20%20%20%20%20%20%EB%B2%95%EB%AC%B4%20%EA%B2%80%ED%86%A0%20%EC%9A%94%EC%B2%AD%EC%84%9C%0A%20%20%20%205.%20%EC%82%AC%EC%97%85%2F%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%0A%20%20%20%20%20%20%EC%8B%A0%EA%B7%9C%20%EC%82%AC%EC%97%85%20%EA%B2%80%ED%86%A0%EC%84%9C%0A%20%20%20%20%20%20%EC%82%AC%EC%97%85%20%EC%B6%94%EC%A7%84%2F%EC%98%88%EC%82%B0%20%EC%8A%B9%EC%9D%B8%EC%84%9C%0A%20%20%20%20%20%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EC%A3%BC%EC%9A%94%20%EC%9D%98%EC%82%AC%EA%B2%B0%EC%A0%95%EC%84%9C%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_2-일반-공통-카테고리-3종" tabindex="-1">2. 일반 / 공통 카테고리 (3종) <a class="header-anchor" href="#_2-일반-공통-카테고리-3종" aria-label="Permalink to &quot;2. 일반 / 공통 카테고리 (3종)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명</th><th style="text-align:center;">전결 평가 기준</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징 및 자동 연동</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>일반 업무 품의서</strong></td><td style="text-align:center;">소요 예산 금액</td><td style="text-align:left;">품의 목적, 주요 추진 내용, 기대 효과, 소요 예산</td><td style="text-align:left;">회사 전반의 일반 안건 승인을 위한 범용 표준 서식</td></tr><tr><td style="text-align:left;"><strong>공문 발신 품의서</strong></td><td style="text-align:center;">-</td><td style="text-align:left;">수신처, 발신 명의, 시행 일자, 공문 본문, 첨부 증빙</td><td style="text-align:left;">최종 승인 완료 시 대외 공식 공문 일련번호 자동 채번 및 직인 날인 연동</td></tr><tr><td style="text-align:left;"><strong>수신 공문 접수보고 및 대응 품의서</strong></td><td style="text-align:center;">-</td><td style="text-align:left;">발신 기관/거래처, 접수 일자, 접수 번호, 공문 제목/요약, 처리 방침(회신공문 발송 / 자체 종결 / 부서 이첩 등), 회신 기한, 검토 의견</td><td style="text-align:left;"><strong>사내 수신 공문 대장과 자동 연동</strong>되며, 접수된 공문의 처리 방침을 보고하고 회신용 대외 공문 발송 품의서와의 유기적 연계를 지원</td></tr></tbody></table><h2 id="_3-인사-근태-카테고리-5종" tabindex="-1">3. 인사 / 근태 카테고리 (5종) <a class="header-anchor" href="#_3-인사-근태-카테고리-5종" aria-label="Permalink to &quot;3. 인사 / 근태 카테고리 (5종)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징 및 자동 연동</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>휴가 / 연차 신청서</strong></td><td style="text-align:left;">휴가 구분(연차/반차/경조/공가/병가), 기간, 차감 일수, 비상연락처</td><td style="text-align:left;">반차(0.5일)/전일(1.0일) 선택에 따른 차감 일수 자동 계산 및 <strong>최종 승인 시 잔여 연차 자동 차감</strong></td></tr><tr><td style="text-align:left;"><strong>출장 신청서</strong></td><td style="text-align:left;">출장지, 출장 목적, 출장 기간, 숙박비·교통비·일비 예상 경비</td><td style="text-align:left;">출장 여비 규정에 따른 예상 경비 산출</td></tr><tr><td style="text-align:left;"><strong>연장 / 휴일근무 신청서</strong></td><td style="text-align:left;">근무 일시, 사전 승인 사유, 예상 근무 시간</td><td style="text-align:left;">주 52시간 근태 관리 사전 승인 연동</td></tr><tr><td style="text-align:left;"><strong>인사 발령 품의서</strong></td><td style="text-align:left;">대상자, 발령 구분(승진/전보/보직 발령), 발령 부서 및 직책</td><td style="text-align:left;"><strong>최종 승인 완료 시 사내 인사 관리 시스템에 보직 발령 자동 반영</strong></td></tr><tr><td style="text-align:left;"><strong>인사 관련 신청서</strong></td><td style="text-align:left;">신청 구분(재직/경력증명서, 교육 신청, 복리후생 지원 등), 신청 사유</td><td style="text-align:left;">각종 인사 총무 지원 요청 원스톱 처리</td></tr></tbody></table><h2 id="_4-회계-자금-카테고리-4종" tabindex="-1">4. 회계 / 자금 카테고리 (4종) <a class="header-anchor" href="#_4-회계-자금-카테고리-4종" aria-label="Permalink to &quot;4. 회계 / 자금 카테고리 (4종)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명</th><th style="text-align:center;">전결 평가 기준</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징 및 자동 연동</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>구매 품의서</strong></td><td style="text-align:center;">구입 총액</td><td style="text-align:left;">품목명, 규격, 수량, 단가, 공급가액, 부가세(VAT), 구입 목적</td><td style="text-align:left;">품목별 소계 및 공급가액/부가세(10%) 자동 계산 그리드 제공</td></tr><tr><td style="text-align:left;"><strong>지출 결의서</strong></td><td style="text-align:center;">지출 금액</td><td style="text-align:left;">지출 회계 계정, 지급 대상자, 지급 기한, 입금 계좌정보, 세금계산서 증빙</td><td style="text-align:left;">본사 회계 시스템 및 프로젝트 자금 집행 전표 연동</td></tr><tr><td style="text-align:left;"><strong>경비 정산서</strong></td><td style="text-align:center;">정산 총액</td><td style="text-align:left;">영수증 사용 일자, 사용처, 금액, 정산 사유, 법인카드 승인번호</td><td style="text-align:left;">출장비 및 법인카드 일상 경비 실비 정산</td></tr><tr><td style="text-align:left;"><strong>선급금 / 가지급금 신청서</strong></td><td style="text-align:center;">신청 금액</td><td style="text-align:left;">신청 금액, 지급 목적, 정산 예정 일자, 지급 계좌</td><td style="text-align:left;">사업비 및 공사비 선지급 사전 승인</td></tr></tbody></table><h2 id="_5-계약-법무-카테고리-3종" tabindex="-1">5. 계약 / 법무 카테고리 (3종) <a class="header-anchor" href="#_5-계약-법무-카테고리-3종" aria-label="Permalink to &quot;5. 계약 / 법무 카테고리 (3종)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명</th><th style="text-align:center;">전결 평가 기준</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징 및 자동 연동</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>계약 체결 품의서</strong></td><td style="text-align:center;">계약 금액</td><td style="text-align:left;">계약 상대방(상호/대표), 계약 금액, 계약 기간, 대금 지급 조건, 주요 조항</td><td style="text-align:left;">계약 체결 사전 의사결정 및 계약서 초안 검토</td></tr><tr><td style="text-align:left;"><strong>계약 변경 / 해지 품의서</strong></td><td style="text-align:center;">증감 금액</td><td style="text-align:left;">원 계약 정보, 변경/해지 사유, 계약금 증감 내역, 정산 조건</td><td style="text-align:left;">기 체결된 계약의 변경 합의서 및 타절 정산 승인</td></tr><tr><td style="text-align:left;"><strong>법무 검토 요청서</strong></td><td style="text-align:center;">-</td><td style="text-align:left;">검토 안건명, 사실관계 요약, 주요 법적 쟁점, 회신 희망일, 계약 초안 첨부</td><td style="text-align:left;">사내외 법무 자문 변호사 및 법무팀 전문 검토 지원</td></tr></tbody></table><h2 id="_6-사업-프로젝트-카테고리-3종" tabindex="-1">6. 사업 / 프로젝트 카테고리 (3종) <a class="header-anchor" href="#_6-사업-프로젝트-카테고리-3종" aria-label="Permalink to &quot;6. 사업 / 프로젝트 카테고리 (3종)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명</th><th style="text-align:center;">전결 평가 기준</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징 및 자동 연동</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>신규 사업 검토서</strong></td><td style="text-align:center;">예상 사업비</td><td style="text-align:left;">대상 사업지 위치/규모, 사업 개요, 수지 분석 요약, 예상 수익률(IRR/ROI)</td><td style="text-align:left;">사업 초기 타당성 검토 및 투자 심의</td></tr><tr><td style="text-align:left;"><strong>사업 추진 / 예산 승인서</strong></td><td style="text-align:center;">승인 예산</td><td style="text-align:left;">사업 실행 계획, 단계별 집행 예산, 인허가 일정, 이사회 의결 사항</td><td style="text-align:left;">대규모 자금 투입 및 본 PF/시행 추진 승인</td></tr><tr><td style="text-align:left;"><strong>프로젝트 주요 의사결정서</strong></td><td style="text-align:center;">-</td><td style="text-align:left;">의사결정 배경, <strong>복수 대안 비교 평가표</strong>, 최종 권고안, 리스크 평가</td><td style="text-align:left;">설계/시공사 선정, 분양가 책정 등 부동산 개발 핵심 의사결정</td></tr></tbody></table><h2 id="_7-동적-맞춤형-서식-확장" tabindex="-1">7. 동적 맞춤형 서식 확장 <a class="header-anchor" href="#_7-동적-맞춤형-서식-확장" aria-label="Permalink to &quot;7. 동적 맞춤형 서식 확장&quot;">​</a></h2><p>18종 기본 서식 외에 특수한 프로젝트 양식이나 비정기 보고서가 필요한 경우:</p><ul><li>관리자 콘솔에서 입력 양식 정의(JSON 스키마)를 등록하면, 시스템이 텍스트, 숫자, 날짜, 선택 목록 등의 입력 항목을 화면에 자동으로 생성합니다.</li><li>별도의 시스템 소스 코드 배포 없이도 신규 양식을 즉시 운영 화면에 추가할 수 있습니다.</li></ul><h2 id="_8-신입사원을-위한-서식-선택-가이드" tabindex="-1">8. 신입사원을 위한 서식 선택 가이드 <a class="header-anchor" href="#_8-신입사원을-위한-서식-선택-가이드" aria-label="Permalink to &quot;8. 신입사원을 위한 서식 선택 가이드&quot;">​</a></h2><ul><li><strong>💡 연차나 반차를 사용하고 싶을 때</strong> ➔ <code>[인사/근태] &gt; 휴가 / 연차 신청서</code>를 작성하세요. 승인 즉시 잔여 휴가가 자동 차감됩니다.</li><li><strong>💡 외근이나 출장 경비를 정산할 때</strong> ➔ <code>[회계/자금] &gt; 경비 정산서</code>를 선택하고 영수증 사진이나 카드 승인 내역을 첨부하세요.</li><li><strong>💡 사무용품이나 비품을 구입해야 할 때</strong> ➔ <code>[회계/자금] &gt; 구매 품의서</code>를 통해 사전 승인을 받으세요.</li><li><strong>💡 외부 기관에 공식 문서를 발송할 때</strong> ➔ <code>[일반/공통] &gt; 공문 발신 품의서</code>를 작성하면 회사 직인 날인과 문서번호 채번이 자동으로 처리됩니다.</li></ul>',15))])}const _=d(A,[["render",B]]);export{b as __pageData,_ as default};
